head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "a1",
        "col2": "a1"
    }, {
        "col1": "a2",
        "col2": "a2"
    }, {
        "col1": "a3",
        "col2": "a3"
    }, {
        "col1": "a4",
        "col2": "a4"
    }, {
        "col1": "a5",
        "col2": "a5"
    }, {
        "col1": "a6",
        "col2": "a6"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.checkLayout = function() {
    var widthAt = parseInt(WebSquare.wUnit.getJq("#autoComplete1_gridViewItemTable").css("width"));
    var widthBox = parseInt(WebSquare.wUnit.getJq("#autoComplete1").css("width"));
    return Math.abs(widthAt - widthBox) < 10;
}
scwin.checkLayout2 = function() {
    var widthAt = parseInt(WebSquare.wUnit.getJq("#sel1_gridViewItemTable").css("width"));
    var widthBox = parseInt(WebSquare.wUnit.getJq("#sel1").css("width"));
    return Math.abs(widthAt - widthBox) < 10;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 autoComplete컴포넌트(역삼각형)를 클릭해서 아이템 목록의 너비가 autoComplete의 너비에 맞게 나타나는 지 확인한다.
    //1. After running the sample, click the autoComplete component (inverted triangle) to see if the width of the item list matches the width of autoComplete.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. 아이템 목록의 너비가 autoComplete의 너비에 맞게 아래로 보여진다.
    //1. The width of the item list is shown below to fit the width of autoComplete.
    WebSquare.wUnit.addCommand("assert", "scwin.checkLayout()", "true");
    //Test step 2. selectbox컴포넌트(역삼각형)를 클릭해서 아이템 목록의 너비가 selectbox의 너비에 맞게 나타나는 지 확인한다.
    //2. Click the selectbox component (inverted triangle) to make sure that the width of the item list matches the width of the selectbox.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('sel1_button').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. 아이템 목록의 너비가 selectbox의 너비에 맞게 아래로 보여진다.
    //2. The width of the item list is shown below the width of the selectbox.
    WebSquare.wUnit.addCommand("assert", "scwin.checkLayout2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 14-Jun-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
